css:
/* Open conversation: centered column, comfortable measure */
[role="main"] [role="list"] {
  max-width: 920px;
  margin-inline: auto;
}
[data-message-id] .a3s {
  max-width: 72ch;
  font-size: 15px !important;
  line-height: 1.6 !important;
}
[data-message-id] .a3s img {
  max-width: 100%;
  height: auto;
}
